From ebc74359e5ba84f3ea236ac1328b86dbe834d902 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:19:12 +0100
Subject: [PATCH] startkde: don't replace the user session's LANG on first
 login

SDDM starts the session with the LANG of /etc/locale.conf, so on first
login that one was saved to plasma-localerc even when environment.d sets
another for users. Use systemd's LANG then, keeping one the DM chose.

BUG: 497501
---
 startkde/startplasma.cpp | 44 +++++++++++++++++++++++++++++++++++++---
 1 file changed, 41 insertions(+), 3 deletions(-)

diff --git a/startkde/startplasma.cpp b/startkde/startplasma.cpp
index 9cda0be1e5..33d8183753 100644
--- a/startkde/startplasma.cpp
+++ b/startkde/startplasma.cpp
@@ -16,6 +16,7 @@
 #include <QDir>
 #include <QElapsedTimer>
 #include <QEventLoop>
+#include <QFile>
 #include <QProcess>
 #include <QStandardPaths>
 #include <QTextStream>
@@ -181,6 +182,30 @@ void createConfigDirectory()
         out << "Could not create config directory XDG_CONFIG_HOME: " << configDir << '\n';
 }

+// The LANG of /etc/locale.conf (or /etc/default/locale), which display managers fall back to
+static QString systemDefaultLang()
+{
+    for (const auto &path : {QStringLiteral("/etc/locale.conf"), QStringLiteral("/etc/default/locale")}) {
+        QFile file(path);
+        if (!file.open(QIODevice::ReadOnly | QIODevice::Text)) {
+            continue;
+        }
+        while (!file.atEnd()) {
+            const QString line = QString::fromUtf8(file.readLine()).trimmed();
+            if (!line.startsWith(QLatin1String("LANG="))) {
+                continue;
+            }
+            QString value = line.mid(5);
+            if (value.size() >= 2 && (value.front() == u'"' || value.front() == u'\'') && value.back() == value.front()) {
+                value = value.sliced(1, value.size() - 2);
+            }
+            return value;
+        }
+        return QString();
+    }
+    return QString();
+}
+
 void runStartupConfig()
 {
     // export LC_* variables set by kcmshell5 formats into environment
@@ -217,9 +242,22 @@ void runStartupConfig()
         qputenv("LANGUAGE", value.toUtf8());
     }

-    if (!formatsConfig.hasKey("LANG") && !qEnvironmentVariableIsEmpty("LANG")) {
-        formatsConfig.writeEntry("LANG", qgetenv("LANG"));
-        formatsConfig.sync();
+    if (!formatsConfig.hasKey("LANG")) {
+        // Display managers like SDDM start us with the system LANG even when the user session has its own one
+        // (e.g. from environment.d), so take systemd's LANG then, but keep a LANG the display manager chose for the user
+        const QString lang = qEnvironmentVariable("LANG");
+        const QString systemLang = systemDefaultLang();
+        if (lang.isEmpty() || lang == systemLang) {
+            const auto systemdEnvironment = getSystemdEnvironment();
+            const QString systemdLang = systemdEnvironment ? systemdEnvironment->value(QStringLiteral("LANG")) : QString();
+            if (!systemdLang.isEmpty() && systemdLang != systemLang) {
+                qputenv("LANG", systemdLang.toUtf8());
+            }
+        }
+        if (!qEnvironmentVariableIsEmpty("LANG")) {
+            formatsConfig.writeEntry("LANG", qgetenv("LANG"));
+            formatsConfig.sync();
+        }
     }
 }

